css:
[data-slot="menu-popup"] [data-variant="destructive"][data-highlighted] { background-color: var(--error-surface) !important; }
:is([data-slot="dialog-footer"], [data-slot="alert-dialog-footer"]) { background-color: transparent !important; border-top-color: transparent !important; }
/* flat buttons: zero Tailwind's shadow vars only, so focus rings (also box-shadow) survive */
:is([data-slot="button"], [data-slot$="-close"], [data-slot$="-action"]), :is([data-slot="button"], [data-slot$="-close"], [data-slot$="-action"])::before { --tw-shadow: 0 0 #0000 !important; --tw-inset-shadow: 0 0 #0000 !important; }
:root { --font-weight-medium: 510 !important; --font-weight-semibold: 590 !important; --font-weight-bold: 680 !important; --default-font-feature-settings: "cv01", "ss03" !important; --radius: .375rem !important; --control-radius: .375rem !important; --surface-grain: none !important; }
/* inset main panel: sidebar-inset is not a stable T3 selector, recheck after nightly updates */
[data-slot="sidebar-inset"] { margin: 8px 8px 8px 0; border: 1px solid var(--border); border-radius: 12px; overflow: hidden; height: calc(100dvh - 16px) !important; min-height: 0 !important; }
/* the inset panel border replaces the sidebar edge; avoid a double separator */
[data-slot="sidebar-container"] { border-right-color: transparent !important; }
/* move top-right controls clear of the inset margin + radius */
:root { --workspace-controls-right: calc(env(safe-area-inset-right) + 1.25rem) !important; }
.wco { --workspace-controls-right: calc(100vw - env(titlebar-area-width, 100vw) - env(titlebar-area-x, 0px) + 1.25rem) !important; }
/* Linear weights: strong text is semibold, not 700 */
strong, b, .chat-markdown strong { font-weight: var(--font-weight-semibold) !important; }
/* sidebar rows: lighter than font-medium (510) so titles do not read as bold */
:is([data-thread-item], [data-sidebar-row]) .font-medium { font-weight: 450 !important; }
/* top-right controls: shift down by the inset margin so top gap matches the right gap */
[class*="right-[var(--workspace-controls-right)]"][class*="top-[var(--workspace-controls-top)]"] { top: calc(var(--workspace-controls-top) + 8px) !important; gap: 1px !important; }
[class*="right-[var(--workspace-controls-right)]"] .gap-1 { gap: 1px !important; }
/* floating surfaces: one Linear-style recipe instead of four shadow/border/glass variants */
:root { --popup-shadow: 0 2px 6px rgb(0 0 0 / 4%), 0 1px 1px rgb(0 0 0 / 3%); }
:root.dark { --popup-shadow: 0 2px 8px rgb(0 0 0 / 24%), 0 1px 1px rgb(0 0 0 / 20%); }
:is([data-slot="menu-popup"], [data-slot="select-popup"], [data-slot="popover-popup"]:not(.bg-transparent), [data-slot="preview-card-popup"], [data-slot="tooltip-popup"], [data-slot="autocomplete-popup"], [data-slot="combobox-positioner"] > span, [data-slot="toast-popup"]) { background: var(--popover) !important; border: 1px solid var(--border) !important; border-radius: 8px !important; box-shadow: var(--popup-shadow) !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
[data-slot="tooltip-popup"] { border-radius: 6px !important; }
:is([data-slot="menu-popup"], [data-slot="select-popup"], [data-slot="popover-popup"], [data-slot="preview-card-popup"], [data-slot="tooltip-popup"], [data-slot="autocomplete-popup"], [data-slot="combobox-positioner"] > span, [data-slot="toast-popup"])::before { display: none !important; }
/* toast close: same surface as popups, shown only on hover or keyboard focus */
[data-slot="toast-close"] { background: var(--popover) !important; border: 1px solid var(--border) !important; box-shadow: var(--popup-shadow) !important; backdrop-filter: none !important; opacity: 0; transition: opacity .1s; }
[data-slot="toast-popup"]:hover [data-slot="toast-close"], [data-slot="toast-close"]:focus-visible { opacity: 1; }
/* hide scrollbars everywhere (native and scroll-area); scrolling still works */
* { scrollbar-width: none !important; }
*::-webkit-scrollbar { display: none !important; }
[data-slot="scroll-area-scrollbar"] { display: none !important; }
